-- request: GET /api/places?select=id&or=(location.bbox_leftof."SRID=4326;POINT(0%200)",location.bbox_rightof."SRID=4326;POINT(100%200)",location.bbox_below."SRID=4326;POINT(0%2040)",location.bbox_above."SRID=4326;POINT(0%2060)")&and=(location.bbox_overlapsorleftof."SRID=4326;POINT(1%200)",location.bbox_overlapsorrightof."SRID=4326;POINT(-1%200)",not.location.bbox_overlapsorbelow."SRID=4326;POINT(0%20-90)",location.bbox_overlapsorabove."SRID=4326;POINT(0%20-90)")&area=bbox_overlapsorleftof.SRID%3D4326%3BPOINT(0%200)&order=id
SELECT json_build_object('has_next', coalesce(bool_or(s1.__rn > $10), false), 'has_prev', false, 'first', (json_agg(s1.__key ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $10))->0, 'last', (json_agg(s1.__key ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $10))->-1, 'n', count(*) FILTER (WHERE s1.__rn <= $10), 'rows', coalesce(json_agg(s1.data ORDER BY s1.__rn ASC) FILTER (WHERE s1.__rn <= $10), '[]'::json)) AS data
FROM (
  SELECT json_build_object('id', t0."id") AS data, jsonb_build_array(t0."id") AS __key, row_number() OVER (ORDER BY t0."id" ASC) AS __rn
  FROM "public"."places" t0
  WHERE (t0."location" |&> CASE WHEN left($1, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($1), 4326) ELSE ST_GeomFromEWKT($1) END AND NOT (t0."location" &<| CASE WHEN left($2, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($2), 4326) ELSE ST_GeomFromEWKT($2) END) AND t0."location" &< CASE WHEN left($3, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($3), 4326) ELSE ST_GeomFromEWKT($3) END AND t0."location" &> CASE WHEN left($4, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($4), 4326) ELSE ST_GeomFromEWKT($4) END) AND t0."area"::geometry &< CASE WHEN left($5, 1) = '{' THEN ST_GeomFromGeoJSON($5) ELSE ST_GeomFromEWKT($5) END AND (t0."location" |>> CASE WHEN left($6, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($6), 4326) ELSE ST_GeomFromEWKT($6) END OR t0."location" <<| CASE WHEN left($7, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($7), 4326) ELSE ST_GeomFromEWKT($7) END OR t0."location" << CASE WHEN left($8, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($8), 4326) ELSE ST_GeomFromEWKT($8) END OR t0."location" >> CASE WHEN left($9, 1) = '{' THEN ST_Transform(ST_GeomFromGeoJSON($9), 4326) ELSE ST_GeomFromEWKT($9) END)
  ORDER BY t0."id" ASC
  LIMIT 101
) s1
-- args: ["SRID=4326;POINT(0 -90)","SRID=4326;POINT(0 -90)","SRID=4326;POINT(1 0)","SRID=4326;POINT(-1 0)","SRID=4326;POINT(0 0)","SRID=4326;POINT(0 60)","SRID=4326;POINT(0 40)","SRID=4326;POINT(0 0)","SRID=4326;POINT(100 0)",100]
